(41558, 'Psalms 86:17', 'Psalms', 86, 17, 'راته دې نښه د نېکۍ وښایه ای څښتنه ما سره مرسته وکړه ماته تسلي راکړه وبه شرمیږي دښمنان زما چې وویني دا', 'راته دې نشه د نېکی وشایه ای چشتنه ما سره مرسته وکره ماته تسلی راکره وبه شرمیزی دشمنان زما چې ووینی دا', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_86_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41559, 'Numbers 2:1', 'Numbers', 2, 1, 'څښتن موسی او هارون ته وویل:', 'چشتن موسی او هارون ته وویل:', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_2_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41560, 'Numbers 2:2', 'Numbers', 2, 2, '«کله چې اسراییلیان خېمې ودروي، هر سړی به د خپلې ډلې د بیرغ او د خپلې طایفې د نښان لاندې خېمې ودروي. کمپ دې د سپېڅلې خېمې په شاوخوا کې جوړ شي.»', '«کله چې اسراییلیان خېمې ودروی، هر سری به د خپلې دلې د بیرغ او د خپلې طایفې د نشان لاندې خېمې ودروی. کمپ دې د سپېچلې خېمې په شاوخوا کې جور شی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_2_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841);